B = (5*sqrt(3),37);
O = (0,0);

draw(A--B--O--cycle);
draw((-5,0)--(40,0));
draw((0,-5)--(0,40));

label("$a + 11i$", A, E);
label("$b + 37i$", B, N);
label("$O$", O, SW);
